SELECT id FROM order_evidence_record WHERE rental_order_id=#{orderId} AND uploaded_by_user_id=#{actor}
  AND evidence_node=#{node} AND evidence_type='photo' AND draft_removed_at IS NULL AND id IN
  #{id}

mapper.update:
UPDATE order_receipt_check SET deadline_at=TIMESTAMPADD(MICROSECOND,remaining_check_ms*1000,GREATEST(start_at,#{at})),
  check_status='pending',remaining_check_ms=NULL,version=version+1,updated_at=#{at}
WHERE rental_order_id=#{orderId} AND check_status='problem_reported' AND remaining_check_ms IS NOT NULL AND start_at IS NOT NULL
